 20	/**
 21	 * Module-owned adapter over the normal OGameX unit queue.
 22	 *
 23	 * The decision is the module's; the queue, its requirements and its prices are the host's. The host
 24	 * service silently returns when the amount is unaffordable, so the planner must have already asked
 25	 * what the planet can pay for -- this adapter only refuses what the host would never accept as a
 26	 * unit, and reports whether a queue row actually appeared.
 27	 */
 28	class QueueAiUnitsAction implements QueueAiUnits
 29	{
 30	    public function __construct(
 31	        private PlayerGameStateService $playerGameStateService,
 32	        private PlanetServiceFactory $planetServiceFactory,
 33	        private UnitQueueService $unitQueueService,
 34	    ) {
 35	    }
 36	
 37	    public function handle(int $playerId, int $planetId, int $unitId, int $amount): AiActionResult
 38	    {
 39	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
 40	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 41	        }
 42	
 43	        if ($amount < 1) {
 44	            return AiActionResult::rejected(AiQueueActionReason::NothingQueueable);
 45	        }
 46	
 47	        try {
 48	            $player = $this->playerGameStateService->advance($playerId, $planetId);
 49	
 50	            if ($player->isBanned()) {
 51	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 52	            }
 53	            if ($player->isInVacationMode()) {
 54	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 55	            }
 56	
 57	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
 58	            $unit = ObjectService::getObjectById($unitId);
 59	            if ($unit->type !== GameObjectType::Ship && $unit->type !== GameObjectType::Defense) {
 60	                return AiActionResult::rejected(AiQueueActionReason::NotAUnit);
 61	            }
 62	
 63	            if ($unit->type === GameObjectType::Defense) {
 64	                return $this->queueDefence($player, $planetId, $unitId, $amount);
 65	            }
 66	
 67	            $this->unitQueueService->add($planet, $unitId, $amount);
 68	            $queueId = UnitQueue::query()
 69	                ->where('planet_id', $planetId)
 70	                ->where('object_id', $unitId)
 71	                ->where('processed', 0)
 72	                ->latest('id')
 73	                ->value('id');
 74	
 75	            return $queueId === null ? AiActionResult::rejected(AiQueueActionReason::QueueNotCreated) : AiActionResult::queued($queueId);
 76	        } catch (Exception $exception) {
 77	            return AiActionResult::rejected($exception->getMessage());
 78	        }
 79	    }
 80	
 81	    /**
 82	     * The defence order, trimmed to what the planet's standing wall has left of the behaviour file's
 83	     * ceiling, with the reading and the writing under one lock.
 84	     *
 85	     * The planner refuses a wall at the ceiling, but a session backlog runs several intents on the
 86	     * same planet at once and each reads the same shortfall before any of them reaches the yard, so
 87	     * the ceiling is applied where the units are written. The planet row is locked across the read
 88	     * and the write, so a worker that waited sees what the one before it bought (live 2 Oct 2026: a
 89	     * planet the file caps at 20,000 units held 24,900, one batch per concurrent worker).
 90	     */
 91	    private function queueDefence(PlayerService $player, int $planetId, int $unitId, int $amount): AiActionResult
 92	    {
 93	        return DB::transaction(function () use ($player, $planetId, $unitId, $amount): AiActionResult {
 94	            DB::table('planets')->where('id', $planetId)->lockForUpdate()->value('id');
 95	
 96	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
 97	            $remaining = app(DefenseCompositionPlanner::class)->remainingCeiling($planet);
 98	            $amount = $remaining === null ? $amount : min($amount, max(0, $remaining));
 99	            // The order was priced a session ago and other work on this planet has spent the balance
100	            // since: the host's add() returns silently for a batch it cannot pay for whole, so the wall
101	            // never appeared while the planet stayed naked (live 2 Oct 2026: 4 x QueueUnits refused with
102	            // queue_not_created). What this planet can pay for now is the order.
103	            $amount = min($amount, ObjectService::getObjectMaxBuildAmount(ObjectService::getObjectById($unitId)->machine_name, $planet, true));
104	            if ($amount < 1) {
105	                return AiActionResult::rejected(AiQueueActionReason::NothingQueueable);
106	            }
107	
